values.value:
[
  [
    {
      "fieldName": "ucinn_ascendv2__Field_Change_Event_Mapping__c",
      "toolTip": "Configuration pertaining to fields on the transaction entry layout that throw events.",
      "jsonFieldParams": {
        "label": "Field Change Event Mapping",
        "type": "object",
        "helpText": "This field fires the event when its changed",
        "keyLabel": "Section Name",
        "keyHelpText": "Section Name from where the event will be triggered from.",
        "jsonKeysToValueList": [
          {
            "key": "[CUSTOM]",
            "helpText": "Specify the section name defined from Related Information Field Map that will trigger this event.",
            "valueType": "object",
            "valueJsonFieldParams": {
              "type": "object",
              "keyLabel": "Object Api Name",
              "keyHelpText": "The object inside this section that you want to fire the event from.",
              "helpText": "object to map of fields and the events that those fields fire.",
              "title": "Object To Field Event Mapping",
              "jsonKeysToValueList": [
                {
                  "key": "[CUSTOM]",
                  "valueType": "object",
                  "valueJsonFieldParams": {
                    "type": "object",
                    "helpText": "Map field to event arguments.",
                    "keyLabel": "Field Api Name",
                    "keyHelpText": "Field of this object that will be firing the event when value changes.",
                    "valueLabel": "Event Definition",
                    "valueHelpText": "Event Name or a json object describing the event with additional parameters.",
                    "jsonKeysToValueList": [
                      {
                        "key": "[CUSTOM]",
                        "valueType": "multi",
                        "valueTypeToFieldParams": {
                          "string": {
                            "type": "text"
                          },
                          "object": {
                            "type": "object",
                            "jsonKeysToValueList": [
                              {
                                "key": "eventName",
                                "helpText": "Name of the even being fired.",
                                "valueCustomFieldParams": {
                                  "type": "text"
                                }
                              },
                              {
                                "key": "fireOnPrepopulation",
                                "helpText": "On prepopulation fire the event.",
                                "valueCustomFieldParams": {
                                  "type": "checkbox"
                                }
                              },
                              {
                                "key": "validationMap",
                                "helpText": "Define validations to run before setting the value and firing events.",
                                "valueJsonFieldParams": {
                                  "type": "object",
                                  "jsonKeysToValueList": [
                                    {
                                      "key": "[CUSTOM]",
                                      "valueJsonFieldParams": {
                                        "type": "object",
                                        "jsonKeysToValueList": [
                                          {
                                            "key": "type",
                                            "valueCustomFieldParams": {
                                              "type": "picklist",
                                              "customPicklistValuesString": [
                                                "notice",
                                                "modal"
                                              ]
                                            }
                                          }
                                        ]
                                      }
                                    }
                                  ]
                                }
                              },
                              {
                                "key": "extraData",
                                "helpText": "Extra data from the front end to be sent to the backend to do certain calculations for this event.",
                                "valueJsonFieldParams": {
                                  "type": "list",
                                  "listType": "value",
                                  "valueCustomFieldParams": {
                                    "type": "text"
                                  }
                                }
                              }
                            ]
                          }
                        }
                      }
                    ]
                  }
                }
              ]
            }
          }
        ]
      }
    },
    {
      "fieldName": "ucinn_ascendv2__Field_Change_Event_Handler_Mapping__c",
      "toolTip": "Configuration pertaining to fields on the transaction entry layout that handle events.",
      "jsonFieldParams": {
        "label": "Field Change Event Handler Mapping",
        "type": "object",
        "helpText": "This catches the event that is fired when a field is changed.",
        "keyLabel": "Section Name",
        "keyHelpText": "Section Name of the related section that will be handling the events that are fired.",
        "jsonKeysToValueList": [
          {
            "key": "[CUSTOM]",
            "helpText": "This maps the Related Information Section name to the events that it should listen for.",
            "valueType": "multi",
            "valueTypeToFieldParams": {
              "object": {
                "type": "object",
                "keyLabel": "Object Api Name",
                "keyHelpText": "Object that will be handling events.",
                "jsonKeysToValueList": [
                  {
                    "key": "[CUSTOM]",
                    "helpText": "Object of this section that will handle this field level events.",
                    "valueJsonFieldParams": {
                      "type": "object",
                      "keyLabel": "Field Api Name",
                      "keyHelpText": "Field that will be handling events.",
                      "jsonKeysToValueList": [
                        {
                          "key": "[CUSTOM]",
                          "valueJsonFieldParams": {
                            "type": "list",
                            "listType": "object",
                            "helpText": "All the events that this field is listening for. When a event listed here is fired this field will handle it.",
                            "jsonKeysToValueList": [
                              {
                                "key": "event",
                                "label": "Event Name",
                                "helpText": "Name of the Event being handled",
                                "valueCustomFieldParams": {
                                  "type": "text"
                                }
                              },
                              {
                                "key": "priority",
                                "label": "Priority",
                                "helpText": "When other fields are also handling the same event what should the order of execution be. Lower number priority means this field will handle this event first. Blank means it will handle this event last.",
                                "valueCustomFieldParams": {
                                  "type": "number"
                                }
                              },
                              {
                                "key": "indexed",
                                "label": "Indexed",
                                "helpText": "Should only the same row index as the field that fired this event handle it.",
                                "valueCustomFieldParams": {
                                  "type": "checkbox"
                                }
                              },
                              {
                                "key": "chain",
                                "label": "Chain",
                                "helpText": "After this field finishes handling this event, should we fire this field that handled the event.",
                                "valueCustomFieldParams": {
                                  "type": "checkbox"
                                }
                              },
                              {
                                "key": "fireOnPrepopulation",
                                "label": "Fire on Prepopulation",
                                "helpText": "On page load do we want to automatically fire this event even when value isn't updated manually or updated by an event.",
                                "valueCustomFieldParams": {
                                  "type": "checkbox"
                                }
                              },
                              {
                                "key": "extraData",
                                "label": "Extra Data",
                                "helpText": "Extra data from the front end to be passed to the backend to do some computation.",
                                "valueJsonFieldParams": {
                                  "type": "list",
                                  "listType": "value",
                                  "valueCustomFieldParams": {
                                    "type": "text"
                                  }
                                }
                              },
                              {
                                "key": "fieldPath",
                                "label": "Field Path",
                                "helpText": "Used when a lookup value is changed it uses this field path to grab a value from that lookup object that was selected and populates this field.",
                                "valueCustomFieldParams": {
                                  "type": "text"
                                }
                              },
                              {
                                "key": "attributePath",
                                "label": "Attribute Path",
                                "helpText": "Define a path to grab a value from the front end. EX) transactionRecords.TransactionInformation.Opportunity.Type",
                                "valueCustomFieldParams": {
                                  "type": "text"
                                }
                              },
                              {
                                "key": "baseDefault",
                                "valueCustomFieldParams": {
                                  "type": "text"
                                }
                              }
                            ]
                          }
                        }
                      ]
                    }
                  },
                  {
                    "key": "componentHandledEvents",
